import '../../src/styles/index.css';import '../../src/styles/atelier.css';
import React,{useState} from 'react';import {createRoot} from 'react-dom/client';import {BrowserRouter} from 'react-router-dom';import '../../src/i18n.js';
import {UIProvider} from '../../src/context/UIContext.jsx';import PhonePreview from '../../src/components/PhonePreview.jsx';import {THEME_CATALOG} from '../../src/config/themeCatalog.js';import {THEME_DEFAULT_SETTINGS} from '../../src/config/themePresets.js';
const base={id:'cover-qa',slug:'cover-qa',weddingDate:'2026-12-20',coupleProfile:{brideName:'Alina',groomName:'Raka',brideFullName:'Alina Putri',groomFullName:'Raka Pratama'},invitationFeatures:{musicEnabled:false,igFilterEnabled:false,rsvpEnabled:false,wishesEnabled:false},events:[],galleryMedia:[],wishes:[]};
function App(){const [theme,setTheme]=useState('wasesa'),[revision,setRevision]=useState(0);return <main style={{minHeight:'100vh',boxSizing:'border-box',padding:18,background:'#eee9dd',font:'13px sans-serif',color:'#4c5945'}}><nav style={{display:'flex',gap:14,alignItems:'center',marginBottom:15}}><label>Template pengujian <select aria-label="Template pengujian" value={theme} onChange={e=>setTheme(e.target.value)}>{THEME_CATALOG.map(t=><option key={t.id} value={t.id}>{t.name}</option>)}</select></label><button onClick={()=>setRevision(r=>r+1)}>Ulangi pembuka</button></nav><div style={{width:390,height:844,position:'relative',margin:'auto',overflow:'hidden'}}><PhonePreview key={theme+revision} invitation={{...base,themeId:theme,themeSettings:{...THEME_DEFAULT_SETTINGS[theme],characterSettings:{mode:'default'}}}} editorPreview/></div></main>}
createRoot(document.getElementById('root')).render(<BrowserRouter><UIProvider><App/></UIProvider></BrowserRouter>);
